import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const CameraRecognition = ({ addNotification }) => {
  // ============ REFS ============
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const detectionIntervalRef = useRef(null);
  const detectionTimeoutRef = useRef(null);
  const progressIntervalRef = useRef(null);

  // ============ STATE ============
  const [cameraActive, setCameraActive] = useState(false);
  const [detecting, setDetecting] = useState(false);
  const [detectionProgress, setDetectionProgress] = useState(0);
  const [enrollmentPhoto, setEnrollmentPhoto] = useState(null);
  const [capturedPhoto, setCapturedPhoto] = useState(null);
  const [matchResult, setMatchResult] = useState(null);
  const [error, setError] = useState(null);
  const [cameraPermission, setCameraPermission] = useState(null);
  const [videoReady, setVideoReady] = useState(false);

  // ============ VÉRIFIER PERMISSIONS CAMÉRA ============
  useEffect(() => {
    const checkCameraPermission = async () => {
      try {
        const result = await navigator.permissions.query({ name: 'camera' });
        setCameraPermission(result.state);
        result.addEventListener('change', () => setCameraPermission(result.state));
      } catch (err) {
        console.warn('⚠️ Permissions API non disponible:', err);
      }
    };
    checkCameraPermission();
  }, []);

  // ============ DÉMARRAGE CAMÉRA (AVEC FIX PC) ============
  const startCamera = async () => {
    try {
      console.log('🎥 Démarrage caméra...');
      setError(null);

      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }

      const constraints = {
        video: {
          facingMode: 'user',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current) {
        videoRef.current.srcObject = stream;

        // --- FIX PC : Force les attributs pour éviter l'écran noir ---
        videoRef.current.setAttribute('muted', '');
        videoRef.current.setAttribute('playsinline', '');
        videoRef.current.muted = true;

        // On attend que la vidéo soit vraiment prête
        videoRef.current.onloadedmetadata = async () => {
          try {
            await videoRef.current.play();
            setVideoReady(true);
            setCameraActive(true);
            console.log('✅ Vidéo en lecture');
          } catch (e) {
            console.error("Erreur lecture auto:", e);
          }
        };
      }
    } catch (err) {
      console.error('❌ Erreur caméra:', err);
      setError('Impossible d\'accéder à la caméra. Vérifiez les permissions.');
    }
  };

  // ============ ARRÊTER CAMÉRA ============
  const stopCamera = () => {
    if (detectionIntervalRef.current) clearInterval(detectionIntervalRef.current);
    if (detectionTimeoutRef.current) clearTimeout(detectionTimeoutRef.current);
    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) videoRef.current.srcObject = null;

    setCameraActive(false);
    setDetecting(false);
    setDetectionProgress(0);
    setVideoReady(false);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  // ============ LANCER DÉTECTION 10 SECONDES ============
  const startDetection = async () => {
    if (!videoRef.current || !cameraActive) return;

    setDetecting(true);
    setDetectionProgress(0);
    setMatchResult(null);
    setError(null);

    let bestMatch = null;
    let startTime = Date.now();
    const DURATION = 10000;

    detectionIntervalRef.current = setInterval(async () => {
      if (!videoRef.current) return;

      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;
      canvas.getContext('2d').drawImage(videoRef.current, 0, 0);
      const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

      try {
        const response = await attendanceAPI.recognize(imageBase64);
        const data = response?.data;

        if (data?.success && data?.student && data?.confidence > 0.35) {
          if (!bestMatch || data.confidence > bestMatch.confidence) {
            bestMatch = { ...data, photo: imageBase64 };
          }
        }
      } catch (e) { console.warn("API loop error"); }
    }, 600);

    // Barre de progression
    progressIntervalRef.current = setInterval(() => {
      const elapsed = Date.now() - startTime;
      setDetectionProgress(Math.min(100, (elapsed / DURATION) * 100));
    }, 100);

    // Fin de détection
    detectionTimeoutRef.current = setTimeout(() => {
      clearInterval(detectionIntervalRef.current);
      clearInterval(progressIntervalRef.current);
      setDetecting(false);

      if (bestMatch) {
        handleDetectionSuccess(bestMatch);
      } else {
        setError('❌ Aucun visage reconnu après 10s.');
      }
    }, DURATION);
  };

  const handleDetectionSuccess = (matchData) => {
    // Capture de la photo actuelle pour l'UI
    const canvas = document.createElement('canvas');
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;
    canvas.getContext('2d').drawImage(videoRef.current, 0, 0);

    setCapturedPhoto(canvas.toDataURL('image/jpeg', 0.92));
    setMatchResult({
      success: true,
      name: matchData.student,
      email: matchData.email || 'N/A',
      confidence: (matchData.confidence * 100).toFixed(1),
      attendanceId: matchData.attendance_id || 'N/A',
      timestamp: new Date().toLocaleTimeString('fr-FR')
    });
    if (addNotification) addNotification(`✅ ${matchData.student} détecté`, 'success');
  };

  const resetDetection = () => {
    setMatchResult(null);
    setCapturedPhoto(null);
    setDetectionProgress(0);
    setError(null);
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>
        <p style={styles.subtitle}>Système de présence automatisé</p>
      </div>

      {cameraPermission && (
        <div style={{...styles.infoBox, borderLeft: `4px solid ${cameraPermission === 'granted' ? COLORS.success : COLORS.danger}`, marginBottom: 20}}>
          <span style={{color: cameraPermission === 'granted' ? '#065F46' : '#7F1D1D'}}>
            {cameraPermission === 'granted' ? '✅ Caméra autorisée' : '⚠️ Accès caméra restreint'}
          </span>
        </div>
      )}

      {cameraActive ? (
        <div style={styles.videoSection}>
          <div style={styles.videoContainer}>
            <video ref={videoRef} autoPlay playsInline muted style={styles.video} />
            <div style={{...styles.statusBadge, background: detecting ? COLORS.primary : COLORS.success}}>
              {detecting ? '🔄 SCANNING...' : '✅ PRÊT'}
            </div>
            {detecting && <div style={styles.timerBadge}>⏱️ {(detectionProgress / 10).toFixed(1)}s / 10s</div>}
          </div>
          {detecting && (
            <div style={styles.progressBar}>
              <div style={{...styles.progressFill, width: `${detectionProgress}%`}} />
            </div>
          )}
        </div>
      ) : (
        <div style={styles.cameraOffBox}>
          <p style={styles.cameraOffText}>📹 Caméra désactivée</p>
          <button onClick={startCamera} style={{...styles.btn, background: COLORS.success, marginTop: 15}}>Allumer la caméra</button>
        </div>
      )}

      <div style={styles.actions}>
        <button onClick={startDetection} disabled={detecting || !cameraActive} style={{...styles.btn, background: (detecting || !cameraActive) ? '#94A3B8' : COLORS.warning}}>
          🔍 Lancer détection 10s
        </button>
        <button onClick={stopCamera} style={{...styles.btn, background: COLORS.danger}}>🛑 Fermer caméra</button>
      </div>

      {error && <div style={styles.errorBox}>{error}</div>}

      {matchResult && (
        <div style={styles.resultSection}>
          <h2 style={styles.resultTitle}>✅ {matchResult.name} détecté!</h2>
          <div style={styles.imagesGrid}>
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>📸 Photo d'Enrôlement</h3>
              <div style={styles.imagePlaceholder}>
                <span style={styles.imagePlaceholderText}>Photo Profile</span>
              </div>
            </div>
            <div style={styles.imageColumn}>
              <h3 style={styles.imageTitle}>🎥 Photo Capturée</h3>
              <div style={styles.imagePlaceholder}>
                <img src={capturedPhoto} alt="Captured" style={styles.image} />
              </div>
            </div>
          </div>

          <div style={styles.infoBox}>
            <div style={styles.infoRow}><span style={styles.infoLabel}>👤 Nom:</span><span>{matchResult.name}</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>🎯 Confiance:</span><span style={{color: COLORS.success, fontWeight: 'bold'}}>{matchResult.confidence}%</span></div>
            <div style={styles.infoRow}><span style={styles.infoLabel}>🕒 Heure:</span><span>{matchResult.timestamp}</span></div>
          </div>

          <button onClick={resetDetection} style={{...styles.btn, background: COLORS.primary, width: '100%'}}>🔄 Nouveau scan</button>
        </div>
      )}
    </div>
  );
};

